<template><view class="flow-page"><jk-page-nav title="库存流水"></jk-page-nav><view v-for="item in list" :key="item.id" class="flow-card"><text class="type">{{item.flowTypeText || flowTypeText(item.flowType)}}</text><text v-if="item.businessTypeText || item.businessType">来源：{{item.businessTypeText || sourceTypeText(item.businessType)}}</text><text>{{item.productName || '商品已删除'}}</text><text>SKU：{{item.skuText || item.skuName || 'SKU 已删除'}}</text><text>可用 {{item.beforeAvailableQty}} → {{item.afterAvailableQty}}</text><text>冻结 {{item.beforeFrozenQty}} → {{item.afterFrozenQty}}</text><text class="time">{{item.createTime}}</text></view><view v-if="!list.length" class="empty">暂无库存流水</view></view></template><script>import{getJkMyStockFlows}from '@/api/jk.js';import JkPageNav from '@/components/jk/jk-page-nav.vue';import{jkSourceTypeText,jkStockFlowTypeText}from '@/utils/jk-display.js';export default{components:{JkPageNav},data(){return{list:[]}},onShow(){getJkMyStockFlows({page:1,limit:50}).then(r=>{this.list=((r.data||r)||{}).list||[]})},methods:{flowTypeText(flowType){return jkStockFlowTypeText(flowType)},sourceTypeText(sourceType){return jkSourceTypeText(sourceType)}}}</script><style scoped>.flow-page{min-height:100vh;padding:24rpx;background:#f3fbf8}.flow-card{display:flex;flex-direction:column;gap:8rpx;margin-bottom:18rpx;padding:25rpx;border-radius:20rpx;background:#fff;color:#55736b;font-size:25rpx;box-shadow:0 10rpx 30rpx rgba(31,122,91,.07)}.type{color:#1f7a5b;font-size:29rpx;font-weight:600}.time{color:#9aaaA5;font-size:22rpx}.empty{text-align:center;padding:90rpx;color:#91a29d}</style>
